"""2026-11-01 W04 有效括号复做；函数占位由导师提供，函数体待本人完成。"""


def is_valid_parentheses(text):
    par={")":"(","]":"[","}":"{"}
    stack=[]
    for i in text:
        if i in "([{":
            stack.append(i)
        else:
            if not stack:
                return False
            if stack.pop()!=par[i]:
                return False
    return not stack
